class Point:
    def __init__(self, name: str, fields: Dict[str, str], srid_map: Dict[str, int]):
        self.name = name
        self.fields = fields
        self.srid_map = srid_map

    def get_field_info(self) -> Dict[str, Tuple[str, int]]:
        field_info = {}
        for field, srid in self.fields.items():
            field_info[field] = (self.srid_map[srid], type(eval(f"x.{field}")))
        return field_info

