import functools
import hashlib
from threading import Lock

def hashkey(args, kwargs):
    return hashlib.md5(functools.repr_(args) + functools.repr_(kwargs)).hexdigest()

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    lock = lock or Lock()
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            lock.acquire()
            try:
                if key(args, kwargs) not in cache:
                    cache[key(args, kwargs)] = func(*args, **kwargs)
                return cache[key(args, kwargs)]
            finally:
                lock.release()
        return wrapper
    return decorator

