import threading

def cachedmethod(cache, key=hash, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    if lock is None:
        lock = threading.RLock()

    def decorator(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            k = key(func, self, args, *kwargs)
            try:
                with lock:
                    result = cache[k]
            except KeyError:
                with lock:
                    result = cache[k] = func(self, *args, **kwargs)
            return result
        return wrapper
    return decorator

