import networkx as nx

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a directed graph
    graph = nx.DiGraph()

    # Add nodes for each class
    for cls in classes:
        graph.add_node(cls)

    # Add edges for each inheritance relationship
    for cls in classes:
        for base in cls.__bases__:
            if base in classes:
                graph.add_edge(base, cls)

    # Find the transitive reduction of the graph
    transitive_reduction = nx.minimum_spanning_tree(graph)

    # Collect the minimal bases
    minimal_bases = []
    for cls in classes:
        if not [n for n in transitive_reduction.neighbors(cls)]:
            minimal_bases.append(cls)

    return minimal_bases

