def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    from typing import List, Union, Tuple, Any

    if output is None:
        output = []

    for item in sequence:
        if isinstance(item, (Declaration, tuple)):
            output.extend(_normalizeargs(item))
        elif isinstance(item, Interface):
            output.append(item)
        elif isinstance(item, ImplementSpec):
            output.extend(item.interfaces)
        else:
            raise ValueError(f"Invalid item in sequence: {item}")

    return output

