def generate_default_observer_schema(app: Application) -> Dict[str, Any]:
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        Dict[str, Any]: A dictionary where keys are resource names and values are default observer schemas.
    """
    default_schemas = {}
    for resource in app.spec.manifest.values():
        if resource.observer_schema is None:
            # Assuming a placeholder for generating a default schema
            resource.observer_schema = {
                "kind": resource.kind,
                "apiVersion": resource.apiVersion,
                "spec": {}
            }
        default_schemas[resource.name] = resource.observer_schema
    return default_schemas

