def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing_digests = []
    unused_digests = []

    for manifest_file in manifest_files:
        if manifest_file.digest not in digests_used:
            missing_digests.append(manifest_file.digest)

    for digest in digests_used:
        if digest not in [manifest_file.digest for manifest_file in manifest_files]:
            unused_digests.append(digest)

    if missing_digests:
        raise ValueError(f"Missing digests: {', '.join(missing_digests)}")

    if unused_digests:
        raise ValueError(f"Unused digests: {', '.join(unused_digests)}")

