def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check if fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check if all required keys are present
    required_keys = {'files', 'algorithm', 'timestamp'}
    if not required_keys.issubset(fixity):
        raise ValueError("Fixity block must contain keys: " + ', '.join(required_keys))

    # Check if files key is a list
    if not isinstance(fixity['files'], list):
        raise ValueError("Files key in fixity block must be a list")

    # Check if all file paths in manifest_files exist in the fixity block
    for file_path in manifest_files:
        if file_path not in fixity['files']:
            raise ValueError("File path " + file_path + " in manifest is not listed in fixity block")

    # Check if all file paths in fixity block are listed in the manifest
    for file_path in fixity['files']:
        if file_path not in manifest_files:
            raise ValueError("File path " + file_path + " in fixity block is not listed in manifest")

    # Check if algorithm key is a string
    if not isinstance(fixity['algorithm'], str):
        raise ValueError("Algorithm key in fixity block must be a string")

    # Check if timestamp key is a string
    if not isinstance(fixity['timestamp'], str):
        raise ValueError("Timestamp key in fixity block must be a string")

