def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for expr in args:
        if expr.type == 'And':
            if expr.left.type == 'Or' and expr.left.left == expr.right:
                new_args.append(expr.left.left)
            elif expr.left.type == 'And' and expr.left.left == expr.right:
                new_args.append(expr.left.left)
            elif expr.right.type == 'Or' and expr.right.right == expr.left:
                new_args.append(expr.right.right)
            elif expr.right.type == 'And' and expr.right.right == expr.left:
                new_args.append(expr.right.right)
        elif expr.type == 'Or':
            if expr.left.type == 'And' and expr.left.right == expr.right:
                new_args.append(expr.left.left)
            elif expr.left.type == 'Or' and expr.left.left == expr.right:
                new_args.append(expr.left.left)
            elif expr.right.type == 'And' and expr.right.left == expr.left:
                new_args.append(expr.right.right)
            elif expr.right.type == 'Or' and expr.right.right == expr.left:
                new_args.append(expr.right.right)
        else:
            new_args.append(expr)
    return new_args

