    """Validate a single object.

    Returns:
        bool - True if the object is valid, False otherwise
    """
    if not obj:
        return False

    if check_digests:
        if not obj.digest:
            if show_warnings:
                print(f"Warning: Object {obj} has no digest")
            return False
        if obj.digest != obj.calculate_digest():
            if show_warnings:
                print(f"Warning: Object {obj} has an invalid digest")
