import hashlib

class InventoryValidator:
    def __init__(self, root_inventory):
        self.root_inventory = root_inventory
        self.content_digests = {}

    def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        for version_dir in version_dirs:
            inventory_path = os.path.join(version_dir, 'inventory.txt')
            if not os.path.exists(inventory_path):
                raise ValueError(f"Inventory file not found for version {version_dir}")

            with open(inventory_path, 'r') as f:
                inventory = f.read()
                if inventory != self.root_inventory:
                    raise ValueError(f"Inventory for version {version_dir} is different from the root inventory")

            for root, dirs, files in os.walk(version_dir):
                for file in files:
                    file_path = os.path.join(root, file)
                    digest = self.calculate_digest(file_path)
                    if file_path in self.content_digests and self.content_digests[file_path] != digest:
                        raise ValueError(f"Content digest for {file_path} has changed between versions")
                    self.content_digests[file_path] = digest

    def calculate_digest(self, file_path):
        """Calculate the SHA-256 digest of a file."""
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

