import copy
from ruamel.yaml import ScalarNode, MappingNode, ListNode

def deep_merge_node(left, right):
    if isinstance(left, MappingNode) and isinstance(right, MappingNode):
        merged = copy.deepcopy(left)
        for key, value in right.value:
            for m_key, m_value in merged.value:
                if key.value == m_key.value:
                    m_value = deep_merge_node(m_value, value)
                    break
            else:
                merged.value.append((key, value))
        return merged
    elif isinstance(left, ListNode) and isinstance(right, ListNode):
        return ListNode([deep_merge_node(lv, rv) for lv, rv in zip(left.value, right.value)])
    elif isinstance(value, ScalarNode):
        return value
    else:
        return right

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:
        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),
    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    result = {}
    for key, value in nodes:
        if key.value in result:
            value = deep_merge_node(result[key.value], value)
        result[key.value] = value
    return [(ScalarNode(tag='tag:yaml.org,2002:str', value=key), value)
            for key, value in result.items()]

