def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    for attr in iface.__dict__:
        if not tentative and attr.startswith('_'):
            continue
        if attr not in candidate.__dict__:
            return False
        if not callable(getattr(iface, attr)) and getattr(iface, attr) != getattr(candidate, attr):
            return False
        if callable(getattr(iface, attr)) and not getattr(candidate, attr) in set(getattr(iface, attr).__closure__):
            return False
    return True

