from typing import Tuple, Set, Callable

def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """

    tags = set()
    in_code_block = False
    result = []
    temp_tag = ""

    for char in text:
        if char == '`':
            if in_code_block:
                # Append the rest of the code block to the result
                result.append(char)
                breaking_index = text.find('`', 1)
                if breaking_index != -1:
                    result.append(text[1:breaking_index + 1])
                    text = text[breaking_index + 1:]
                    in_code_block = False
                    continue
            else:
                in_code_block = True
        elif in_code_block:
            result.append(char)
        else:
            if char == '<':
                temp_tag = ""
            elif char == '>':
                if temp_tag:
                    tags.add(temp_tag)
                    if replacer:
                        result.append(replacer(temp_tag))
                    else:
                        result.append(temp_tag)
                    temp_tag = ""
                else:
                    result.append(char)
            elif temp_tag:
                temp_tag += char
            else:
                result.append(char)

    if temp_tag:
        tags.add(temp_tag)
        if replacer:
            result.append(replacer(temp_tag))
        else:
            result.append(temp_tag)

    return tags, "".join(result)

