    except yaml.YAMLError as exc:
        raise IRValidatorException(f"Error parsing YAML content: {exc}")

    required_fields = cls.REQUIRED_FIELDS  # Assuming REQUIRED_FIELDS is a class attribute

    for field in required_fields:
        if field not in spec_dict:
            raise IRValidatorException(f"Missing required field: {field}")

    return spec_dict

