def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for key, value in parser_dict.items():
        if key == 'include':
            if isinstance(value, list):
                for item in value:
                    self._include_groups(item)
            elif isinstance(value, dict):
                self._include_groups(value)
            else:
                raise ValueError(f"Invalid value for include directive: {value}")
        elif key == 'group':
            if isinstance(value, dict):
                for group_key, group_value in value.items():
                    self._include_groups(group_value)
            else:
                raise ValueError(f"Invalid value for group directive: {value}")
        else:
            setattr(self, key, value)

